const state = { view: location.hash.slice(1) || "today", recommendation: "active", selectedAssumption: null, intakePreview: null, intakeDraft: null, intakeFollowUpQuestions: [], onboardingLoading: false, onboardingLoadingStartedAt: null, onboardingStep: 0, planLoading: false, assumptionFilter: "all", completionTaskId: null, showTaskForm: false, showExperimentForm: false, showAssumptionForm: false, experimentMenuId: null, completingExperimentId: null, linkingEvidenceId: null, loading: true, projectId: null, project: null, projects: [], assumptions: [], evidence: [], experiments: [], tasks: [], decisions: [], roadmapMilestones: [], roadmapGraph: { nodes: [], edges: [] }, memoryItems: [], events: [], chatTurns: [], chatSessions: [], chatSessionId: null, chatTopic: "general", pendingPlanItems: [], discoveryFacts: [], discoveryPlan: null, chatRecommendation: null, checkpointSynthesis: null, checkpointError: "", changeSets: [], approvedChangeSets: [], rejectedChangeSets: [], chatLoading: false, chatLoadedProject: null, chatError: "", chatDraft: "", chatSubmitting: false, chatCapture: "", chatSelectedId: null };
let onboardingProgressTimer = null;
const toTitle = value => String(value || "").split("_").map(part => part[0] ? part[0].toUpperCase() + part.slice(1) : "").join(" ");
const experimentColumn = status => ({ running: "Active", proposed: "Proposed", completed: "Completed", paused: "Proposed", failed: "Completed" })[status] || toTitle(status);
const dateLabel = value => value ? new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" }).format(new Date(value)) : "No due date";
async function request(url, options = {}) { const response = await fetch(url, { headers: { "Content-Type": "application/json", ...(options.headers || {}) }, ...options }); const body = response.status === 204 ? null : await response.json(); if (!response.ok) throw new Error(body.error || "Request failed"); return body; }
function hydrate(memory) { const p = memory.project; state.projectId = p.id; state.project = { name: p.name, shortDescription: p.short_description || "", targetCustomer: p.target_customer || "", targetBuyer: "", problem: p.problem_statement || "", solution: p.solution_summary || "", pricing: p.pricing_hypothesis || "", revenueModel: p.revenue_model || "", salesMotion: "", validation: p.validation_stage || p.stage || "idea", firstDollarPath: p.first_dollar_path || {}, checkpointStatus: p.checkpoint_status || "not_ready" }; const links = memory.assumption_evidence || []; state.assumptions = memory.assumptions.map(a => ({ id:a.id, statement:a.statement, category:a.category, status:a.status, priority:toTitle(a.priority), confidence:toTitle(a.confidence), risk:a.risk_score, blocker:a.revenue_blocker, evidence:links.filter(l => l.assumption_id === a.id).length, why:a.subcategory || "This belief needs direct evidence before it can guide the company." })); state.evidence = memory.evidence.map(e => ({ id:e.id, source:toTitle(e.source_type), person:e.source_person_name || e.source_title, date:dateLabel(e.source_date || e.created_at), summary:e.summary, strength:toTitle(e.strength), signal:toTitle(e.behavior_vs_opinion), links:links.filter(l => l.evidence_id === e.id).map(l => ({ id:l.assumption_id, relationship:toTitle(l.relationship) })) })); state.experiments = memory.experiments.map(e => ({ id:e.id, title:e.title, kind:experimentColumn(e.status), assumption:e.assumption_id, hypothesis:e.hypothesis, method:e.test_design || "", metric:e.success_metric, due:e.expected_duration || "No due date", status:toTitle(e.status), result:e.status === "completed" ? (e.test_design || "Result recorded.") : "" })); state.tasks = memory.tasks.map(t => ({ id:t.id, title:t.title, description:t.description || "", status:t.status, priority:toTitle(t.priority), impact:toTitle(t.impact_level || "medium"), firstRevenue:t.impact_level === "first_revenue", minutes:t.estimated_minutes || 20, assumption:t.assumption_id, experiment:t.experiment_id, today:t.status !== "done" })); state.decisions = memory.decisions; state.roadmapMilestones = memory.roadmap_milestones || []; state.memoryItems = memory.memory_items || []; state.events = memory.events.map(event => event.summary); state.selectedAssumption ||= state.assumptions[0]?.id || null; state.loading = false; }
async function loadProjects() { const { projects } = await request("/api/projects"); state.projects = projects.filter(project => project.status === "active"); }
async function loadMemory(projectId = state.projectId) { state.loading = true; render(); try { const [memory] = await Promise.all([request(`/api/projects/${projectId}/memory`), loadProjects()]); hydrate(memory); try { state.chatRecommendation = (await request(`/api/projects/${projectId}/recommendation`)).recommendation || null; state.roadmapGraph = await request(`/api/projects/${projectId}/roadmap-graph`); } catch { /* Today can still use its task fallback when recommendations are temporarily unavailable. */ } } catch (error) { state.loading = false; toast(error.message); } render(); }
// Static contract retained for browser smoke tests: request(`/api/projects/${projectId}/chat`)
async function loadChatContext(force = false) { if (!state.projectId || state.chatLoading || (!force && state.chatLoadedProject === state.projectId)) return; const projectId = state.projectId; state.chatLoading = true; render(); try { const sessionQuery = state.chatSessionId ? `?session_id=${encodeURIComponent(state.chatSessionId)}` : ""; const [chat, recommendation, proposals, sessions, memoryItems] = await Promise.all([request(`/api/projects/${projectId}/chat${sessionQuery}`), request(`/api/projects/${projectId}/recommendation`), request(`/api/projects/${projectId}/change-sets`), request(`/api/projects/${projectId}/sessions`), request(`/api/projects/${projectId}/memory-items`)]); if (state.projectId !== projectId) return; state.chatTurns = chat.turns || []; state.discoveryFacts = chat.discovery_facts || []; state.discoveryPlan = chat.discovery_plan || null; state.pendingPlanItems = chat.pending_plan_items || []; state.chatRecommendation = recommendation.recommendation || null; state.changeSets = proposals.change_sets || []; state.chatSessions = sessions.sessions || []; state.memoryItems = memoryItems.memory_items || []; state.chatLoadedProject = projectId; } catch (error) { if (state.projectId === projectId) state.chatError = error.message; } finally { if (state.projectId === projectId) { state.chatLoading = false; render(); } } }
function chatRefresh() { state.chatLoadedProject = null; return loadChatContext(true); }
async function mutate(path, method, body) { try { await request(path, { method, body: body ? JSON.stringify(body) : undefined }); await loadMemory(); } catch (error) { toast(error.message); } }
function draftProject(payload) { return { name: payload.name || "New project", shortDescription: payload.short_description || "", targetCustomer: payload.target_customer || "", targetBuyer: "", problem: payload.problem_statement || "", solution: payload.solution_summary || "", pricing: payload.pricing_hypothesis || "", revenueModel: "Subscription", salesMotion: "", validation: payload.validation_stage || payload.stage || "idea" }; }

const $ = (s) => document.querySelector(s);
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"})[c]);
const label = (id) => state.assumptions.find(a => a.id === id)?.statement || "—";
const badge = (value, kind = "") => `<span class="badge ${kind || value.toLowerCase().replaceAll(" ", "-")}">${esc(value)}</span>`;
const titleCase = (s) => s[0].toUpperCase() + s.slice(1);

function layout(title, eyebrow, content, action = "") { return `<section class="page"><header class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1></div>${action}</header>${content}</section>`; }
function progress() { const done = state.tasks.filter(t=>t.status === "done").length; return `<div class="revenue-progress"><div><span>Path to first dollar</span><strong>${done} of 5 validation moves complete</strong></div><div class="progress-track"><i style="width:${done / 5 * 100}%"></i></div><small>Current focus: secure a paid pilot</small></div>`; }
function nextAction(){return [...state.tasks].filter(t=>t.status!=="done").sort((a,b)=>Number(b.firstRevenue)-Number(a.firstRevenue)||({High:3,Medium:2,Low:1}[b.priority]-({High:3,Medium:2,Low:1}[a.priority])))[0];}
function dueTone(due, completed){const day=Number(String(due).match(/\d+/)?.[0]);if(completed||!day||day<3)return "past";return day-3<=2?"urgent":day-3<=7?"soon":"upcoming";}
function taskRow(t, compact=false) { const validation=state.completionTaskId===t.id?`<form class="completion-form" id="completionForm" data-id="${t.id}"><label>What proves this task is complete?<input name="proof" placeholder="e.g. Invitation sent and reply tracked" required></label><button class="button primary" type="submit">Confirm completion</button><button type="button" class="text-button" data-action="cancel-completion">Cancel</button></form>`:""; return `<article class="task-row ${t.status === "done" ? "is-done" : ""}"><button class="check ${t.status === "done" ? "checked" : ""}" data-action="toggle-task" data-id="${t.id}" aria-label="Mark task ${t.status === "done" ? "incomplete" : "complete"}">${t.status === "done" ? "✓" : ""}</button><div class="task-main"><div class="task-title">${esc(t.title)}${t.firstRevenue?` ${badge("First revenue","first-revenue")}`:""}</div>${compact ? "" : `<p>${esc(t.description)}</p>`}<div class="task-meta">${badge(titleCase(t.priority))} <span>${esc(t.impact)} impact</span><span>${t.minutes} min</span>${t.status !== "done" ? `<button class="text-button" data-action="continue-task-in-chat" data-id="${t.id}">Talk through it →</button>` : ""}</div>${validation}</div>${!compact ? `<span class="task-state">${titleCase(t.status)}</span>` : ""}</article>`; }
function assumptionCard(a, featured=false) { return `<article class="assumption-card ${featured ? "featured" : ""} ${state.selectedAssumption === a.id ? "selected" : ""}" data-action="select-assumption" data-id="${a.id}"><div class="assumption-top"><span class="category">${esc(a.category)}</span>${badge(a.status)}</div><h3>${esc(a.statement)}</h3><div class="assumption-stats"><span><b>${a.risk}</b> risk score</span><span>${a.evidence} evidence ${a.evidence === 1 ? "link" : "links"}</span>${a.blocker ? `<span class="blocker">◆ Revenue blocker</span>` : ""}</div><div class="confidence"><i style="width:${a.risk}%"></i></div><p class="why"><strong>Why this matters:</strong> <span contenteditable="true" data-action="edit-assumption-why" data-id="${a.id}">${esc(a.why)}</span></p>${a.status==="untested"?`<button class="text-button test-button" data-action="mark-testing" data-id="${a.id}">Mark as being tested</button>`:""}</article>`; }

function today() {
 const rec = state.recommendation;
 const task = nextAction() || { title:"Create your first validation task", description:"Turn the next customer-learning step into a concrete task.", assumption:null, minutes:15 }; const exp = state.experiments.find(e=>e.status==="Running") || state.experiments[0] || { title:"No active experiment", status:"Proposed", hypothesis:"Create an experiment tied to your riskiest assumption.", metric:"Define a behavior-based success metric", due:"—" }; const risky = state.assumptions.find(a=>a.id===state.selectedAssumption) || state.assumptions[0] || { risk:0, category:"No assumptions yet", statement:"Add the belief that most affects first revenue.", why:"Company memory is ready for your first assumption." };
 const recommendation = state.chatRecommendation?.recommendation, recommendationAction = recommendation?.action_payload?.title || recommendation?.action_payload?.action || task.title;
 const recBlock = rec === "active" ? `<article class="next-action"><div class="action-label"><span class="spark">✦</span> ${recommendation ? "COFOUNDER RECOMMENDATION" : "YOUR NEXT BEST ACTION"}</div><h2>${esc(recommendationAction)}</h2><p>${esc(recommendation?.reason || task.description)}</p><div class="action-details"><div><span>Top issue</span><strong>${esc(recommendation?.primary_issue || label(task.assumption))}</strong></div><div><span>Recommended state</span><strong>${esc(toTitle(recommendation?.state || "task"))}</strong></div><div><span>Confidence</span><strong>${recommendation ? `${Math.round((recommendation.confidence || 0) * 100)}%` : `${task.minutes} min`}</strong></div></div><div class="action-buttons"><button class="button primary" data-action="open-chat">Open Cofounder <span>→</span></button><button class="button ghost" data-action="focus-task" data-id="${task.id}">Tasks</button><button class="text-button" data-action="dismiss-rec">Dismiss</button></div></article>` : `<article class="next-action muted"><div class="action-label"><span class="spark">✦</span> RECOMMENDATION ${rec === "snoozed" ? "SNOOZED" : "DISMISSED"}</div><h2>${rec === "snoozed" ? "We'll bring this back tomorrow." : "Choose your next focus."}</h2><p>${rec === "snoozed" ? "Use this space to keep moving on your active experiment." : "Review your open tasks to select the most important next move."}</p><button class="button ghost" data-action="restore-rec">Restore recommendation</button></article>`;
 return layout("Good morning, Sarah.", "Monday, August 3", `<div class="today-grid"><div class="main-column">${recBlock}<section class="section"><div class="section-heading"><div><p class="eyebrow">ACTIVE EXPERIMENT</p><h2>${esc(exp.title)}</h2></div>${badge(exp.status)}</div><div class="experiment-summary"><div><span>Hypothesis</span><p>${esc(exp.hypothesis)}</p></div><div><span>Success looks like</span><p>${esc(exp.metric)}</p></div><div><span>Due</span><p>${esc(exp.due)}</p></div></div><a class="inline-link" href="#experiments" data-view-link="experiments">View experiment details →</a></section><section class="section"><div class="section-heading"><div><p class="eyebrow">OPEN TASKS</p><h2>Keep the momentum</h2></div><a class="inline-link" href="#tasks" data-view-link="tasks">See all tasks →</a></div><div class="task-list">${state.tasks.filter(t=>t.status!=="done").slice(0,3).map(t=>taskRow(t,true)).join("")}</div></section><section class="section"><p class="eyebrow">RECENT ACTIVITY</p><div class="task-list">${state.events.slice(0,4).map(event=>`<div class="task-row"><span class="source-dot"></span><div class="task-main"><div class="task-title">${esc(event)}</div></div></div>`).join("")}</div></section></div><aside class="right-column"><section class="risk-panel"><p class="eyebrow">TOP RISK</p><h2>${risky.risk}<small>/100</small></h2><span class="risk-caption">${esc(risky.category)}</span><h3>${esc(risky.statement)}</h3><p>${esc(risky.why)}</p><a href="#assumptions" data-view-link="assumptions" class="inline-link">Explore assumptions →</a></section><section class="evidence-mini"><div class="section-heading"><div><p class="eyebrow">RECENT EVIDENCE</p><h2>What you learned</h2></div></div>${state.evidence.slice(0,2).map(e=>`<div class="mini-evidence"><span class="source-dot"></span><div><strong>${esc(e.person)}</strong><p>${esc(e.summary)}</p></div></div>`).join("")}<a href="#evidence" data-view-link="evidence" class="inline-link">View evidence inbox →</a></section>${progress()}</aside></div>`);
}

function memoryField(labelText, key, source) { return `<div class="memory-field"><span>${labelText}</span><div><strong contenteditable="true" data-action="edit-memory" data-key="${key}" spellcheck="false">${esc(state.project[key])}</strong>${badge(source, source === "user confirmed" ? "confirmed" : source === "user provided" ? "provided" : "inferred")}${source === "llm inferred" ? `<button class="confirm" data-action="confirm-field" data-key="${key}">Confirm</button>` : ""}</div></div>`; }
function memory() { return layout("Company memory", "THE STRUCTURED STORY OF YOUR COMPANY", `<div class="memory-intro"><p>These are the facts ${esc(state.project.name)} is operating from. Edit any field to write it to persistent company memory.</p><span class="legend">${badge("user provided", "provided")}${badge("llm inferred", "inferred")}${badge("user confirmed", "confirmed")}</span></div><div class="memory-grid"><section class="memory-card"><p class="eyebrow">CORE IDENTITY</p>${memoryField("Company", "name", "user confirmed")}${memoryField("Description", "shortDescription", "user provided")}${memoryField("Validation stage", "validation", "llm inferred")}</section><section class="memory-card"><p class="eyebrow">CUSTOMER & PROBLEM</p>${memoryField("Target customer", "targetCustomer", "user confirmed")}${memoryField("Initial buyer", "targetBuyer", "llm inferred")}${memoryField("Pain to solve", "problem", "user confirmed")}</section><section class="memory-card"><p class="eyebrow">SOLUTION & BUSINESS MODEL</p>${memoryField("Solution", "solution", "user provided")}${memoryField("Pricing hypothesis", "pricing", "user confirmed")}${memoryField("Revenue model", "revenueModel", "llm inferred")}${memoryField("Sales motion", "salesMotion", "llm inferred")}</section><section class="memory-card decisions-card"><p class="eyebrow">ACTIVE DECISIONS</p>${state.decisions.map(d=>`<article class="decision"><strong>${esc(d.title)}</strong><p>${esc(d.decision)}</p><small>${esc(d.reason || "")}</small></article>`).join("") || `<div class="empty-state">No decisions saved yet.</div>`}</section></div>`); }
function memoryWorkspace() { const groups=[...new Set(state.memoryItems.map(item=>item.aspect))]; return layout("Company memory", "THE EVIDENCE-BACKED STORY OF YOUR COMPANY", `<div class="memory-intro"><p>Every important idea is attributed to a company aspect, confidence level, and source. Working memory can be corrected before it becomes a stronger belief.</p><span class="legend">${badge("founder statement", "confirmed")}${badge("inference", "inferred")}${badge("low confidence", "low")}${badge("high confidence", "high")}</span></div><div class="memory-grid"><section class="memory-card"><p class="eyebrow">COMPANY SNAPSHOT</p>${memoryField("Company", "name", "user confirmed")}${memoryField("Description", "shortDescription", "user provided")}${memoryField("Target customer", "targetCustomer", "user confirmed")}${memoryField("Problem", "problem", "user confirmed")}${memoryField("Solution", "solution", "user provided")}</section>${groups.map(group=>`<section class="memory-card"><p class="eyebrow">${esc(toTitle(group))}</p>${state.memoryItems.filter(item=>item.aspect===group).map(item=>`<article class="memory-item"><strong>${esc(item.statement)}</strong><div>${badge(toTitle(item.classification),item.classification)} ${badge(`${toTitle(item.confidence)} confidence`,item.confidence)} ${item.review_state!=="confirmed"?badge("working","inferred"):""}</div><small>Source ${esc((item.source_turn_ids||[]).join(", ") || "checkpoint context")}</small></article>`).join("") || `<div class="empty-state">No items yet.</div>`}</section>`).join("")}</div>`); }

function assumptions() { const all=[...state.assumptions].sort((a,b)=>b.risk-a.risk), list=all.filter(a=>state.assumptionFilter==="all"||state.assumptionFilter==="blockers"&&a.blocker||state.assumptionFilter==="untested"&&a.status==="untested"); return layout("Assumptions", "WHAT MUST BE TRUE FOR THIS COMPANY TO WORK", `<div class="assumption-hero"><div><p>Every early company is a stack of unproven beliefs. Test the most consequential ones first.</p><div class="filter-chips"><button class="chip ${state.assumptionFilter==="all"?"active":""}" data-action="filter-assumptions" data-filter="all">All (${all.length})</button><button class="chip ${state.assumptionFilter==="blockers"?"active":""}" data-action="filter-assumptions" data-filter="blockers">Revenue blockers</button><button class="chip ${state.assumptionFilter==="untested"?"active":""}" data-action="filter-assumptions" data-filter="untested">Untested</button><button class="chip" data-action="show-assumption-form">+ Add assumption</button></div></div><div class="risk-explainer"><span>Risk score</span><strong>${all[0]?.risk ?? "—"}${all.length ? "/100" : ""}</strong><p>Impact + uncertainty + revenue blocker − evidence</p></div></div>${state.showAssumptionForm?`<form class="evidence-form" id="assumptionForm"><label>Assumption<input name="statement" required placeholder="What must be true?"></label><div class="form-grid"><label>Category<select name="category"><option>Problem</option><option>Willingness to pay</option><option>Distribution</option><option>Solution</option></select></label><label>Priority<select name="priority"><option>High</option><option>Medium</option><option>Low</option></select></label></div><label>Why it matters (editable later)<input name="why" required placeholder="How it affects this company"></label><button class="button primary">Save assumption</button></form>`:""}<div class="assumption-list">${list.map((a,i)=>assumptionCard(a,i===0)).join("") || `<div class="empty-state">No assumptions match this filter.</div>`}</div>`); }

function evidence() { return layout("Evidence inbox", "MARKET LEARNING, CONNECTED TO WHAT YOU BELIEVE", `<div class="evidence-layout"><div><div class="evidence-toolbar"><p>${state.evidence.length} pieces of market evidence</p><button class="button primary" data-action="show-evidence-form">+ Add evidence</button></div><form class="evidence-form hidden" id="evidenceForm"><div class="form-grid"><label>Source type<select name="source"><option>Manual note</option><option>Customer interview</option><option>Sales call</option></select></label><label>Who / source title<input name="person" placeholder="e.g. Jamie, 8th grade teacher" required></label><label>Signal type<select name="signal"><option>Opinion</option><option>Stated intent</option><option>Behavior</option><option>Payment</option></select></label><label>Strength<select name="strength"><option>Weak</option><option>Moderate</option><option>Strong</option></select></label></div><label>What did you learn?<textarea name="summary" placeholder="Paste an interview note or market observation…" required></textarea></label><div class="form-actions"><button class="button primary" type="submit">Save draft evidence</button><button class="button ghost" type="button" data-action="hide-evidence-form">Cancel</button></div></form><div class="evidence-list">${state.evidence.map(e=>evidenceCard(e)).join("")}</div></div><aside class="evidence-side"><p class="eyebrow">EVIDENCE QUALITY</p><h2>Strength is a founder-reviewed judgment.</h2><ol><li><b>Strong:</b> payment, commitment, or repeated behavior</li><li><b>Moderate:</b> specific pain or stated intent</li><li><b>Weak:</b> a single opinion or vague encouragement</li></ol><p>The source, recency, specificity, and whether the signal is behavior—not opinion—inform the initial suggestion. The founder can override it.</p></aside></div>`); }
function evidenceCard(e) { const linker=state.linkingEvidenceId===e.id?`<form class="link-form" id="linkForm" data-id="${e.id}"><select name="assumption">${state.assumptions.map(a=>`<option value="${a.id}">${esc(a.statement)}</option>`).join("")}</select><select name="relationship"><option>Supports</option><option>Contradicts</option><option>Neutral</option></select><button class="button primary">Link</button></form>`:""; return `<article class="evidence-card"><div class="evidence-head"><div><span class="source-icon">◌</span><span class="source-type">${esc(e.source)}</span><h3>${esc(e.person)}</h3></div><small>${esc(e.date)}</small></div><p>${esc(e.summary)}</p><div class="evidence-footer">${badge(e.strength)} ${badge(e.signal, "signal")}<div class="linked">${e.links.map(l=>`<button data-action="select-assumption" data-id="${l.id}"><span class="link-${l.relationship.toLowerCase()}">●</span>${esc(l.relationship)}: ${esc(label(l.id))}</button>`).join("")}</div><button class="text-button" data-action="link-evidence" data-id="${e.id}">+ Link assumption</button></div>${linker}</article>`; }

function experiments() { const groups = ["Active","Proposed","Completed"]; return layout("Experiments", "TEST BELIEFS WITH REAL CUSTOMER BEHAVIOR", `<div class="evidence-toolbar"><p class="page-intro">A good experiment produces a decision, not just more opinions.</p><button class="button primary" data-action="show-experiment-form">+ Propose experiment</button></div>${state.showExperimentForm?`<form class="evidence-form" id="experimentForm"><label>Experiment title<input name="title" required placeholder="What will you test?"></label><label>Hypothesis<textarea name="hypothesis" required></textarea></label><div class="form-grid"><label>Related assumption<select name="assumption">${state.assumptions.map(a=>`<option value="${a.id}">${esc(a.statement)}</option>`).join("")}</select></label><label>Due date<input name="due" value="Aug 12" required></label></div><label>Success metric<input name="metric" required placeholder="e.g. 2 paid pilots"></label><button class="button primary">Save proposed experiment</button></form>`:""}<div class="experiment-board">${groups.map(group=>`<section class="experiment-column"><header><h2>${group}</h2><span>${state.experiments.filter(e=>e.kind===group).length}</span></header>${state.experiments.filter(e=>e.kind===group).map(experimentCard).join("") || `<div class="empty-state">Nothing here yet.</div>`}</section>`).join("")}</div>`); }
function experimentCard(e) { const related = label(e.assumption), due=dueTone(e.due,e.kind==="Completed"), menu=state.experimentMenuId===e.id?`<div class="card-menu"><button data-action="record-result" data-id="${e.id}">Record result</button><button data-action="start-experiment" data-id="${e.id}">Start</button></div>`:"", resultForm=state.completingExperimentId===e.id?`<form class="completion-form" id="experimentResultForm" data-id="${e.id}"><label>Result and learning<textarea name="result" required placeholder="What happened? What changes next?"></textarea></label><label>Did the success metric pass?<select name="metricStatus"><option>Met</option><option>Partially met</option><option>Not met</option></select></label><button class="button primary">Complete experiment</button></form>`:""; return `<article class="experiment-card"><div class="experiment-card-top">${badge(e.status)}<button class="more-button" data-action="experiment-menu" data-id="${e.id}" aria-label="Experiment options">•••</button>${menu}</div><h3>${esc(e.title)}</h3><p>${esc(e.hypothesis)}</p><div class="experiment-detail"><span>Success metric ${e.metricStatus?`· ${esc(e.metricStatus)}`:""}</span><strong>${esc(e.metric)}</strong></div><div class="experiment-foot"><span class="due ${due}">Due ${esc(e.due)}</span><button class="assumption-link" data-action="select-assumption" data-id="${e.assumption}">${esc(related)}</button></div>${e.status === "Proposed" ? `<button class="button full" data-action="start-experiment" data-id="${e.id}">Start experiment</button>` : e.status === "Running" ? `<button class="button full" data-action="record-result" data-id="${e.id}">Record result & complete</button>` : ""}${resultForm}${e.result ? `<div class="result"><strong>Result · Metric ${esc(e.metricStatus)}</strong>${esc(e.result)}</div>` : ""}</article>`; }

function tasks() { const groups=[{name:"Today",filter:t=>t.today&&t.status!=="done"},{name:"Upcoming",filter:t=>!t.today&&t.status!=="done"},{name:"Done",filter:t=>t.status==="done"}], first=state.tasks.filter(t=>t.firstRevenue&&t.status!=="done"); return layout("Tasks", "CONCRETE WORK TIED TO FIRST REVENUE", `<div class="tasks-layout"><div><div class="task-summary"><span><b>${state.tasks.filter(t=>t.status!=="done").length}</b> open tasks</span><span><b>${first.length}</b> tied to first revenue</span><button class="button ghost" data-action="add-task">+ Add task</button></div>${state.showTaskForm?`<form class="evidence-form" id="taskForm"><label>Task title<input name="title" required placeholder="Describe the concrete action"></label><label>Description<input name="description" required placeholder="What does done look like?"></label><div class="form-grid"><label>Priority<select name="priority"><option>High</option><option>Medium</option><option>Low</option></select></label><label><input type="checkbox" name="firstRevenue"> Directly tied to first revenue</label></div><button class="button primary">Create task</button></form>`:""}${groups.map(g=>`<section class="task-group"><h2>${g.name}<span>${state.tasks.filter(g.filter).length}</span></h2>${state.tasks.filter(g.filter).map(t=>taskRow(t)).join("") || `<div class="empty-state">Nothing here yet.</div>`}</section>`).join("")}</div>${first.length?`<aside class="task-aside"><p class="eyebrow">FOCUS FOR ${esc(state.project.name)}</p><h2>${esc(state.project.firstDollarPath.revenue_milestone || "Secure a first payment.")}</h2><p>${first.length} open tasks are tied to this first-dollar path.</p><div class="first-dollar-card"><span>◆</span><div><strong>Company-specific trigger</strong><p>Keep the first offer focused until payment evidence exists.</p></div></div></aside>`:""}</div>`); }

function roadmap() { const path=state.project.firstDollarPath||{}, milestones=state.roadmapMilestones.slice(0,4), planNotice=state.planLoading?`<div class="plan-pending" role="status"><span class="spark">✦</span><div><strong>Creating your validation plan</strong><p>Your confirmed profile and assumptions are already saved. Tasks, experiments, and milestones will appear here shortly.</p></div></div>`:""; const related=milestone=>({assumptions:state.assumptions.filter(a=>a.id===milestone.assumption_id),evidence:state.evidence.filter(e=>e.links.some(link=>link.id===milestone.assumption_id)),experiments:state.experiments.filter(e=>e.assumption===milestone.assumption_id),tasks:state.tasks.filter(t=>t.assumption===milestone.assumption_id||t.firstRevenue)}); const hiddenCount=state.roadmapGraph.nodes.filter(node=>!node.visible).length; return layout("First-dollar roadmap", "FOUR MAJOR MOVES TO PAYMENT", `<section class="roadmap-hero"><p>Primary path</p><h2>${esc(path.revenue_milestone||"Define the first paid outcome")}</h2><div>${[["Customer",path.target_segment],["Offer",path.offer],["Channel",path.channel],["Price",path.pricing_offer]].map(([labelText,value])=>`<span><small>${labelText}</small><strong>${esc(value||"Not confirmed")}</strong></span>`).join("")}</div></section>${planNotice}<p class="page-intro">The four steps below are the visible path. ${hiddenCount ? `${hiddenCount} supporting assumptions, experiments, and tasks sit underneath it.` : "Supporting work will appear as the plan is generated."}</p><div class="roadmap-flow">${milestones.map(milestone=>{const items=related(milestone);return `<section class="roadmap-step"><header><span>${milestone.position}</span><div><p class="eyebrow">${esc(toTitle(milestone.status))}</p><h2>${esc(milestone.title)}</h2><p>${esc(milestone.description)}</p><small>Success metric: ${esc(milestone.success_metric)}</small></div></header><div class="roadmap-links">${items.assumptions.map(a=>`<article><strong>Risk</strong><p>${esc(a.statement)}</p></article>`).join("")}${items.evidence.map(e=>`<article><strong>Evidence · ${esc(e.person)}</strong><p>${esc(e.summary)}</p></article>`).join("")}${items.tasks.map(t=>taskRow(t,true)).join("")||"<p>No linked action yet.</p>"}</div></section>`;}).join("")||`<div class="empty-state">${state.planLoading?"Your plan is being generated…":"No saved milestones yet."}</div>`}</div>`); }

function onboardingSteps(){return ["Understanding your company and industry","Choosing one path to first revenue","Identifying the three riskiest assumptions"];}
function intake() { if(state.onboardingLoading){const steps=onboardingSteps(),loaderElapsed=(Date.now()-(state.onboardingLoadingStartedAt||Date.now()))/1000,isFinalStep=state.onboardingStep===steps.length-1;return layout("Building your starting plan", "AI ONBOARDING", `<section class="onboarding-loading"><span class="spark">✦</span><h2>Turning your idea into a plan…</h2><p>We’re preparing one connected draft. Nothing is being saved yet.</p><ol class="onboarding-progress">${steps.map((step,index)=>`<li class="${index<state.onboardingStep?"complete":index===state.onboardingStep?"current":""}"><i>${index<state.onboardingStep?"✓":index+1}</i><span>${esc(step)}</span>${index===state.onboardingStep?"<b>Working</b>":""}</li>`).join("")}</ol><div class="onboarding-loader" role="status" aria-live="polite"><div class="onboarding-loader-track"><i style="animation-delay:-${loaderElapsed}s"></i></div><span>Awaiting AI response</span>${isFinalStep?"<small>This final step may take a little longer.</small>":""}</div></section>`);} const followUps=state.intakeFollowUpQuestions.length?`<section class="empty-state"><strong>We need a little more context before creating a plan.</strong><p>${state.intakeFollowUpQuestions.map(esc).join("<br>")}</p></section>`:""; return layout("Start with the messy version.", "AI ONBOARDING", `${followUps}<form class="intake-form intake-only" id="intakeForm"><label class="large-label">What are you building, who is it for, and what progress have you made?<textarea name="idea" required placeholder="I’m building an AI tool that helps teachers grade homework faster…"></textarea></label><div class="form-grid"><label>Target customer <input name="customer"></label><label>Problem <input name="problem"></label><label>Proposed solution <input name="solution"></label><label>Pricing guess <input name="price"></label><label>Current progress <input name="progress"></label><label>First revenue milestone <small>The first paid result you want to achieve—not your long-term vision. Example: “Get two customers to pay for a pilot.”</small><input name="goal" placeholder="e.g. Get two customers to pay for a pilot"></label></div><button class="button primary" type="submit">Create editable draft <span>→</span></button></form>`); }
function onboardingReview() { const draft=state.intakeDraft; if(!draft)return intake(); const labels={name:"AI project title",short_description:"Description",target_customer:"Target customer",problem_statement:"Problem",solution_summary:"Solution",revenue_model:"Revenue model",pricing_hypothesis:"Pricing hypothesis",stage:"Current stage",founder_goal:"First revenue milestone"}, title=value=>String(value||"").replaceAll("_"," ").replace(/\b\w/g,c=>c.toUpperCase()), industry=draft.industry, path=draft.primary_revenue_path; return layout("Review your starting plan", "ONBOARDING REVIEW", `<form class="onboarding-review" id="onboardingConfirmForm"><p class="page-intro">Keep, edit, or reject the suggested details before they become company memory.</p><section><h2>Company profile</h2><div class="review-grid">${Object.entries(draft.profile).map(([key,item])=>`<label>${labels[key]}<input name="profile-${key}" value="${esc(item.value)}"><small>${key==="name"?"AI-generated project title · saved when you confirm":`${esc(item.confidence)} confidence · uncheck to reject`}</small>${key==="name"?"":`<input type="checkbox" name="accept-profile" value="${key}" ${item.value?"checked":""}> Keep this field`}</label>`).join("")}</div></section><section><h2>Primary path to first dollar</h2><p class="page-intro">Keep one customer, offer, channel, and price focused until it is tested.</p><div class="review-grid">${Object.entries(path).map(([key,item])=>`<label>${title(key)}<input name="revenue-path-${key}" value="${esc(item.value)}"><small>${esc(item.confidence)} confidence</small><input type="checkbox" name="accept-revenue-path" value="${key}" ${item.value?"checked":""}> Keep this path field</label>`).join("")}</div></section><section><h2>Industry classification</h2><p class="page-intro">This guides the initial validation plan. It is an AI suggestion, not a fact.</p><div class="review-grid"><label>Primary industry<select name="industry-primary">${["saas","marketplace","education","local_service","ecommerce","healthcare","other"].map(value=>`<option value="${value}" ${industry.primary_industry===value?"selected":""}>${title(value)}</option>`).join("")}</select><small>${esc(industry.industry_confidence)} confidence · ${esc(industry.industry_rationale||"No rationale provided")}</small><input type="checkbox" name="accept-industry" value="primary_industry" checked> Keep classification</label><label>Secondary industry<input name="industry-secondary" value="${esc(industry.secondary_industry)}" placeholder="Optional"><small>Used only to tune risks and tasks</small><input type="checkbox" name="accept-industry" value="secondary_industry" ${industry.secondary_industry?"checked":""}> Keep this field</label><label>Classification rationale<input name="industry-rationale" value="${esc(industry.industry_rationale)}"><input type="checkbox" name="accept-industry" value="industry_rationale" ${industry.industry_rationale?"checked":""}> Keep this field</label></div><div class="review-grid industry-details">${Object.entries(industry.industry_details).map(([key,item])=>`<label>${title(key)}<input name="industry-detail-${key}" value="${esc(item.value)}"><small>${esc(item.confidence)} confidence</small><input type="checkbox" name="accept-industry-detail" value="${key}" ${item.value?"checked":""}> Keep this field</label>`).join("")}</div></section><section><h2>Risks to validate</h2>${draft.assumptions.map(a=>`<label class="review-item"><input type="checkbox" name="accept-assumption" value="${a.draft_id}" checked><span><strong>${esc(a.statement)}</strong><small>${esc(a.validation_criterion)} · ${esc(a.category)} · ${esc(a.priority)} priority · ${a.risk_score} risk — ${esc(a.rationale)}</small></span></label>`).join("")}</section><section><h2>Next actions</h2>${draft.tasks.map(t=>`<label class="review-item"><input type="checkbox" name="accept-task" value="${t.draft_id}" checked><span><strong>${esc(t.title)}</strong><small>Target: ${esc(t.target_segment)} · ${esc(t.target_quantity)} · Due: ${esc(t.deadline)} · Success: ${esc(t.success_metric)}</small><small>${esc(t.rationale)} Next: ${esc(t.next_step)}</small></span></label>`).join("")}</section><div class="form-actions"><button class="button primary" type="submit">Confirm selected onboarding outputs →</button><button class="button ghost" type="button" data-action="back-to-intake">Edit idea</button></div></form>`); }

function relatedRecords(payload = {}) { const ids = [...new Set([...(payload.source_ids || []), payload.assumption_id, payload.experiment_id, payload.evidence_id, payload.task_id, payload.target_entity_id].filter(Boolean))]; const records = [...state.assumptions.map(x=>[x.id,"Assumption",x.statement]), ...state.evidence.map(x=>[x.id,"Evidence",x.person || x.summary]), ...state.experiments.map(x=>[x.id,"Experiment",x.title]), ...state.tasks.map(x=>[x.id,"Task",x.title])]; return ids.map(id => { const record=records.find(([recordId])=>recordId===id); return record ? `<span class="related-chip">${esc(record[1])}: ${esc(record[2])}</span>` : `<span class="related-chip unresolved">Related record unavailable</span>`; }).join(""); }
function changeSetCard(set, rejected = false) { const items=set.items || []; const selectable=items.filter(item=>item.review_status==="pending"), approved=set.status==="approved"; return `<article class="change-set-card ${rejected?"rejected":""}"><div class="change-set-head"><div><p class="eyebrow">${rejected?"REJECTED PROPOSAL":approved?"APPROVED PROPOSAL":"PENDING PROPOSAL"}</p><h3>${esc(set.rationale || "Suggested memory updates")}</h3></div>${badge(toTitle(set.status || (rejected?"rejected":"pending_review")))}</div>${items.map(item=>`<label class="proposal-item"><input type="checkbox" name="change-set-item" value="${item.id}" ${item.review_status==="pending"?"checked":"disabled"} data-change-set="${set.id}"><span><strong>${esc(toTitle(item.operation))} ${esc(toTitle(item.record_type))}</strong><small>${esc(item.current_payload?.title || item.current_payload?.statement || item.current_payload?.summary || item.current_payload?.reason || "No summary supplied")}</small><small>Provenance: ${esc((item.current_payload?.source_ids || []).join(", ") || set.source_turn_id || "conversation")}</small><span class="related-records">${relatedRecords({...item.current_payload,target_entity_id:item.target_entity_id})}</span>${item.rejection_reason?`<small>Reason: ${esc(item.rejection_reason)}</small>`:""}</span></label>`).join("")}${!rejected?`<div class="proposal-actions">${approved?`<button class="button primary" data-action="apply-change-set" data-id="${set.id}">Apply approved</button>`:`<button class="button primary" data-action="approve-change-set" data-id="${set.id}">Approve all</button>${selectable.length>1?`<button class="button ghost" data-action="approve-selected-change-set" data-id="${set.id}">Approve selected</button>`:""}<button class="text-button" data-action="reject-change-set" data-id="${set.id}">Reject</button>`}</div>`:""}</article>`; }
function chat() { const conversation=state.chatLoading&&!state.chatTurns.length?`<div class="empty-state">Loading conversation…</div>`:state.chatTurns.length?state.chatTurns.map(turn=>`<article class="chat-turn ${turn.actor_type==="founder"?"founder":"cofounder"}"><span>${turn.actor_type==="founder"?"You":"Cofounder"}</span><p>${esc(turn.content)}</p></article>`).join(""):`<div class="empty-state">What are you thinking about today? Bring me the messy version and we’ll find the useful next step together.</div>`; const sessions=state.chatSessions.map(session=>`<button class="chip ${session.id===state.chatSessionId?"active":""}" data-action="select-chat-session" data-id="${session.id}">${esc(session.title || session.topic)}</button>`).join(""); const plan=state.pendingPlanItems[0]; return layout("Your cofounder", "A SHARED MEMORY FOR THE COMPANY", `<div class="cofounder-toolbar"><div><p class="page-intro">${esc(state.project?.name || "Your company")} · ${esc(state.chatTopic)}</p>${sessions}</div><button class="button ghost" data-action="new-topic-chat">+ New topic</button></div><div class="discovery-layout"><section class="chat-main">${state.chatError?`<div class="chat-error" role="alert">${esc(state.chatError)} <button class="text-button" data-action="refresh-chat">Try again</button></div>`:""}<div class="conversation" aria-live="polite">${conversation}</div>${plan?`<div class="chat-next"><span class="eyebrow">WHAT WE COULD EXPLORE NEXT</span><p>${esc(plan.prompt)}</p></div>`:""}<form id="chatForm" class="chat-composer"><textarea name="message" placeholder="Tell your cofounder what you’re thinking…">${esc(state.chatDraft)}</textarea><button class="button primary" ${state.chatSubmitting?"disabled":""}>${state.chatSubmitting?"Sending…":"Send"}</button></form></section><aside class="learning-panel"><p class="eyebrow">COMPANY MEMORY</p><h2>A working picture</h2><p class="learning-intro">Facts are grouped by aspect and carry their confidence and source.</p><div class="learning-list">${state.memoryItems.slice(0, 8).map(item=>`<div class="learning-item"><span>${esc(toTitle(item.aspect))}</span><strong>${esc(item.statement)}</strong><small>${esc(toTitle(item.classification))} · ${esc(toTitle(item.confidence))} confidence</small></div>`).join("") || discoveryLearning()}</div></aside></div>`); }
function discoveryMode(){ return Boolean(state.projectId && state.view !== "checkpoint-review" && state.projects.find(project => project.id === state.projectId)?.onboarding_state === "discovery"); }
function discoveryLearning(){ const items=[]; const add=(labelText,value,status="Listening")=>{ if(value) items.push(`<div class="learning-item"><span>${esc(labelText)}</span><strong>${esc(value)}</strong><small>${esc(status)}</small></div>`); }; const project=state.project||{}; add("Project idea",project.shortDescription,"From your conversation"); add("Who it may help",project.targetCustomer,"From your conversation"); add("Problem to understand",project.problem,"Needs more context"); add("Possible solution",project.solution,"AI is organizing this"); state.discoveryFacts.forEach(fact=>add(toTitle(fact.field_key),fact.statement,`${toTitle(fact.classification)} · ${toTitle(fact.confidence)} confidence`)); state.chatTurns.filter(turn=>turn.actor_type==="ai").forEach(turn=>{ const payload=turn.structured_payload||{}; (payload.proposed_belief_updates||[]).forEach(item=>add(toTitle(item.classification||"Working belief"),item.statement,"Needs your confirmation")); (payload.proposed_records||[]).filter(item=>item.type==="evidence").forEach(item=>add("Evidence mentioned",item.payload?.summary||item.payload?.title,"Needs your confirmation")); }); return items.length ? items.join("") : `<div class="learning-empty"><span>✦</span><p>As you talk, I’ll keep a visible working summary here—ideas, people, problems, and open questions.</p></div>`; }
function discoveryChat(){ const conversation=state.chatLoading&&!state.chatTurns.length?`<div class="empty-state">Loading conversation…</div>`:state.chatTurns.length?state.chatTurns.map(turn=>`<article class="chat-turn ${turn.actor_type==="founder"?"founder":"cofounder"}"><span>${turn.actor_type==="founder"?"You":"Cofounder"}</span><p>${esc(turn.content)}</p></article>`).join(""):`<div class="empty-state">Tell me about the idea you can’t stop thinking about. It does not need to be polished.</div>`; const checkpointReady=Boolean(state.discoveryPlan?.checkpoint_ready || state.project?.checkpointStatus === "ready"), showDiscoveryIntro=!state.chatTurns.some(turn=>turn.actor_type==="founder"); return layout("Your cofounder", "START WITH THE MESSY VERSION", `<div class="discovery-layout"><section class="chat-main">${state.chatError?`<div class="chat-error" role="alert">${esc(state.chatError)} <button class="text-button" data-action="refresh-chat">Try again</button></div>`:""}${showDiscoveryIntro?`<section class="discovery-intro"><span class="spark">✦</span><h2>Let’s find the shape of this together.</h2><p>I’ll ask a few focused questions and keep a working summary beside our conversation. Nothing becomes company memory until you confirm the first checkpoint.</p></section>`:""}<div class="conversation" aria-live="polite">${conversation}</div><form id="chatForm" class="chat-composer"><textarea name="message" placeholder="Tell your cofounder what you’re thinking…">${esc(state.chatDraft)}</textarea><button class="button primary" ${state.chatSubmitting?"disabled":""}>${state.chatSubmitting?"Sending…":"Send"}</button></form>${checkpointReady?`<section class="checkpoint-card"><div><p class="eyebrow">A NATURAL PAUSE</p><h2>This idea has enough shape to give it a name.</h2><p>Choose a name with your cofounder, then review the working snapshot together. Nothing is activated until you confirm it.</p></div><button class="button primary" data-action="complete-checkpoint">Brainstorm a name and review →</button></section>`:""}</section><aside class="learning-panel"><p class="eyebrow">WHAT I’M LEARNING</p><h2>A working picture</h2><p class="learning-intro">This updates as we talk. AI inferences stay marked until you confirm them.</p><div class="learning-list">${discoveryLearning()}</div></aside></div>`); }
function checkpointReview(){ const synthesis=state.checkpointSynthesis; if(!synthesis)return layout("Review company snapshot", "FIRST CHECKPOINT", `<div class="empty-state">Loading snapshot…</div>`); const labels={short_description:"Short description",target_customer:"Target customer",problem_statement:"Problem",solution_summary:"Solution",founder_goal:"Founder goal",pricing_hypothesis:"Pricing hypothesis",first_dollar_path:"First-dollar path",primary_industry:"Primary industry"}; const fields=Object.entries(synthesis.fields).map(([key,item])=>`<label class="checkpoint-field">${labels[key]}<input name="${key}" value="${esc(item.value)}" placeholder="${item.status==="unresolved"?"Not supported yet":""}"><small>${badge(toTitle(item.status),item.status)} ${badge(`${item.confidence} confidence`,item.confidence)} ${item.status==="founder_stated"?"Founder-stated":"AI organized / needs review"}</small></label>`).join(""); return layout("Review company snapshot", "FIRST CHECKPOINT", `<form id="checkpointConfirmForm" class="onboarding-review"><p class="page-intro">Only confirmed fields become company memory. Discovery facts and conversation history stay intact.</p>${state.checkpointError?`<div class="chat-error" role="alert">${esc(state.checkpointError)}</div>`:""}<section><h2>Company profile</h2><label class="checkpoint-field">Company name<input name="name" value="${esc(synthesis.company_name.value)}" placeholder="${esc(synthesis.company_name_suggestion?.value||"Required")}" required><small>${synthesis.company_name_suggestion?`Suggestion only: ${esc(synthesis.company_name_suggestion.value)} · `:""}Founder must choose the name.</small></label><div class="review-grid">${fields}</div></section><section><h2>Open gaps</h2><p class="page-intro">${synthesis.unresolved_gaps.map(gap=>`${esc(gap.label)}: ${esc(gap.question)}`).join(" · ")||"No unresolved core gaps."}</p></section><div class="form-actions"><button class="button primary" type="submit">Confirm snapshot and activate →</button><button class="button ghost" type="button" data-action="continue-discovery">Continue discovery</button></div></form>`); }

const baseDiscoveryLearning = discoveryLearning;
discoveryLearning = function(){ const latest = [...state.chatTurns].reverse().find(turn => turn.actor_type === "founder"); const latestContext = latest ? `<div class="learning-item"><span>Latest founder context</span><strong>${esc(latest.content.slice(0, 220))}${latest.content.length>220?"…":""}</strong><small>Captured from your message</small></div>` : ""; return baseDiscoveryLearning() + latestContext; };
const views = {chat:()=>discoveryMode()?discoveryChat():chat(), cofounder:()=>discoveryMode()?discoveryChat():chat(), "checkpoint-review":checkpointReview, today, roadmap, intake, "onboarding-review": onboardingReview, memory:memoryWorkspace, assumptions, evidence, experiments, tasks};
function emptyProject() { return layout("Start with your cofounder", "A CONVERSATION-FIRST WORKSPACE", `<div class="empty-state">Start with the messy version of your idea. Your cofounder will help shape it into a useful working picture.<br><br><button class="button primary" data-action="new-project">Start a conversation →</button></div>`); }
function attachCancelControls(){const controls={intakeForm:"cancel-intake",taskForm:"cancel-task-form",assumptionForm:"cancel-assumption-form",linkForm:"cancel-link-form",experimentForm:"cancel-experiment-form",experimentResultForm:"cancel-experiment-result"};Object.entries(controls).forEach(([id,action])=>{const form=document.getElementById(id);if(!form||form.querySelector(`[data-action="${action}"]`))return;const button=document.createElement("button");button.type="button";button.className="button ghost cancel-button";button.dataset.action=action;button.textContent="Cancel";form.append(button);});}
function render() { state.view = location.hash.slice(1) || state.view || "today"; if (discoveryMode() && state.view !== "chat" && state.view !== "cofounder") { state.view="chat"; if(location.hash!=="#chat") history.replaceState(null,"","#chat"); } if (!views[state.view]) state.view="today"; const app = $("#app"); app.innerHTML = state.loading ? `<section class="page"><div class="empty-state">Loading company memory…</div></section>` : (!state.project && !["intake","onboarding-review"].includes(state.view) ? emptyProject() : views[state.view]()); document.querySelectorAll(".nav-link").forEach(l=>l.classList.toggle("active", l.dataset.viewLink===state.view || (state.view==="cofounder"&&l.dataset.viewLink==="chat"))); attachCancelControls(); app.focus({preventScroll:true}); updateCounts(); updateProjectChrome(); const conversation=document.querySelector(".conversation"); if(conversation) conversation.scrollTop=conversation.scrollHeight; if ((state.view==="chat"||state.view==="cofounder") && state.project) loadChatContext(); }
function updateCounts(){ $("#riskCount").textContent=state.assumptions.filter(a=>a.risk>=70).length; $("#taskCount").textContent=state.tasks.filter(t=>t.status!=="done").length; }
function updateProjectChrome(){ const name=state.project?.name || "No project loaded", stage=discoveryMode()?"Discovery conversation":toTitle(state.project?.validation || "database memory"); document.querySelector(".project-switcher strong").textContent=name; document.querySelector(".project-switcher small").textContent=stage; document.querySelectorAll("[data-gated-nav]").forEach(link=>link.classList.toggle("hidden",discoveryMode())); const menu=$("#projectMenu"), otherProjects=state.projects.filter(project=>project.id!==state.projectId); menu.innerHTML=`<p>ACTIVE PROJECTS</p>${otherProjects.map(project=>`<button type="button" class="project-option" data-action="switch-project" data-id="${project.id}">${esc(project.name)} <small>${esc(toTitle(project.validation_stage || project.stage || "idea"))}</small></button>`).join("") || `<p class="project-menu-empty">No other active projects</p>`}<button type="button" data-action="new-project">+ Start a new project</button>`; }
function toast(msg) { const el=$("#toast"); el.textContent=msg; el.classList.add("show"); setTimeout(()=>el.classList.remove("show"),2600); }

document.addEventListener("click", e=>{
 const link=e.target.closest("[data-view-link]"); if(link){ e.preventDefault(); location.hash=link.dataset.viewLink; return; }
 const button=e.target.closest("[data-action]"); if(!button) return; const {action,id,key}=button.dataset;
 if(action==="toggle-task"){ const task=state.tasks.find(t=>t.id===id); if(task.status==="done"){mutate(`/api/projects/${state.projectId}/tasks/${id}`,"PATCH",{status:"todo"});}else{state.completionTaskId=id;toast("Add completion evidence before marking this done.");render();} }
 if(action==="select-assumption"){state.selectedAssumption=id; location.hash="assumptions";}
 if(action==="focus-task"){state.view="tasks"; location.hash="tasks"; toast("Your focused task is ready.");}
 if(action==="open-chat"){location.hash="chat";}
 if(action==="select-chat-session"){state.chatSessionId=id;const session=state.chatSessions.find(item=>item.id===id);state.chatTopic=session?.topic||"general";state.chatLoadedProject=null;render();}
 if(action==="new-topic-chat"){const topic=window.prompt("What should this conversation help with?", "Customer interviews");if(topic){request(`/api/projects/${state.projectId}/sessions`,{method:"POST",body:JSON.stringify({topic,title:topic})}).then(({session})=>{state.chatSessionId=session.id;state.chatTopic=session.topic;state.chatLoadedProject=null;render();}).catch(error=>toast(error.message));}}
 if(action==="continue-task-in-chat"){const task=state.tasks.find(item=>item.id===id);state.chatDraft=task?`I completed this task: ${task.title}. Here is what happened: `:"I completed this task. Here is what happened: ";location.hash="chat";}
 if(action==="refresh-chat"){chatRefresh();}
 if(action==="capture-task"){state.chatCapture="task";state.chatSelectedId=state.tasks.find(task=>task.status!=="done")?.id||null;render();}
 if(action==="capture-evidence"){state.chatCapture="evidence";state.chatSelectedId=null;render();}
 if(action==="capture-experiment"){state.chatCapture="experiment";state.chatSelectedId=state.experiments.find(experiment=>String(experiment.status).toLowerCase()!=="completed")?.id||null;render();}
 if(action==="cancel-chat-capture"){state.chatCapture="";render();}
 if(action==="select-chat-task"||action==="select-chat-experiment"){state.chatSelectedId=id;render();}
 if(action==="submit-capture"){const detail=$("#chatCaptureText")?.value.trim(); const task=state.tasks.find(item=>item.id===state.chatSelectedId), experiment=state.experiments.find(item=>item.id===state.chatSelectedId); const selected=task||experiment; const prefix=state.chatCapture==="task"?`I completed this task${selected?`: ${selected.title}`:""}.`:state.chatCapture==="evidence"?"I have new evidence:":`I recorded an experiment result${selected?`: ${selected.title}`:""}.`; if(!detail){toast("Add a short update first.");return;} state.chatDraft=`${prefix} ${detail}`;state.chatCapture="";render();document.querySelector("#chatForm textarea")?.focus();}
 if(action==="approve-change-set"||action==="apply-change-set"){const endpoint=action==="approve-change-set"?"approve":"apply";request(`/api/projects/${state.projectId}/change-sets/${id}/${endpoint}`,{method:"POST"}).then(({change_set})=>{const existing=[...state.changeSets,...state.approvedChangeSets].find(set=>set.id===id);if(endpoint==="approve")state.approvedChangeSets=[{...(existing||{}),...change_set,items:existing?.items||[]},...state.approvedChangeSets.filter(set=>set.id!==id)];else state.approvedChangeSets=state.approvedChangeSets.filter(set=>set.id!==id);chatRefresh();if(endpoint==="apply")loadMemory();}).catch(error=>{state.chatError=error.message;render();});}
 if(action==="approve-selected-change-set"){const itemIds=[...document.querySelectorAll(`[data-change-set="${id}"]:checked`)].map(input=>input.value);request(`/api/projects/${state.projectId}/change-sets/${id}/approve-items`,{method:"POST",body:JSON.stringify({item_ids:itemIds})}).then(({change_set})=>{const existing=state.changeSets.find(set=>set.id===id);if(change_set.status==="approved")state.approvedChangeSets=[{...(existing||{}),...change_set,items:existing?.items||[]},...state.approvedChangeSets.filter(set=>set.id!==id)];chatRefresh();}).catch(error=>{state.chatError=error.message;render();});}
 if(action==="reject-change-set"){const reason=window.prompt("Why are you rejecting this proposal? (optional)");if(reason===null)return;request(`/api/projects/${state.projectId}/change-sets/${id}/reject`,{method:"POST",body:JSON.stringify({reason})}).then(({change_set})=>{const existing=state.changeSets.find(set=>set.id===id);state.rejectedChangeSets=[{...(existing||{}),...change_set,items:existing?.items||[]} ,...state.rejectedChangeSets.filter(set=>set.id!==id)];chatRefresh();}).catch(error=>{state.chatError=error.message;render();});}
 if(action==="snooze-rec"){state.recommendation="snoozed";toast("Recommendation snoozed until tomorrow.");render();}
 if(action==="dismiss-rec"){state.recommendation="dismissed";toast("Recommendation dismissed.");render();}
 if(action==="restore-rec"){state.recommendation="active";toast("Recommendation restored.");render();}
 if(action==="confirm-field"){const map={targetCustomer:"target_customer",problem:"problem_statement",solution:"solution_summary",pricing:"pricing_hypothesis"}, project=state.project || state.intakeDraft; if(state.projectId && project && map[key]) mutate(`/api/projects/${state.projectId}`,"PATCH",{[map[key]]:project[key]});}
 if(action==="show-evidence-form"){$("#evidenceForm").classList.remove("hidden");button.classList.add("hidden");}
 if(action==="hide-evidence-form"){$("#evidenceForm").classList.add("hidden");document.querySelector("[data-action=show-evidence-form]").classList.remove("hidden");}
 if(action==="filter-assumptions"){state.assumptionFilter=button.dataset.filter;render();}
 if(action==="show-assumption-form"){state.showAssumptionForm=true;render();}
 if(action==="mark-testing"){mutate(`/api/projects/${state.projectId}/assumptions/${id}`,"PATCH",{status:"testing"});}
 if(action==="link-evidence"){state.linkingEvidenceId=id;render();}
 if(action==="show-experiment-form"){state.showExperimentForm=true;render();}
 if(action==="experiment-menu"){state.experimentMenuId=state.experimentMenuId===id?null:id;render();}
 if(action==="record-result"){state.completingExperimentId=id;state.experimentMenuId=null;render();}
 if(action==="start-experiment"){mutate(`/api/projects/${state.projectId}/experiments/${id}`,"PATCH",{status:"running",started_at:new Date().toISOString()});}
 if(action==="add-task"){state.showTaskForm=true;render();}
 if(action==="cancel-completion"){state.completionTaskId=null;render();}
 if(action==="toggle-project-menu"){$("#projectMenu").classList.toggle("hidden");}
 if(action==="switch-project"){if(id!==state.projectId){$("#projectMenu").classList.add("hidden");loadMemory(id);}}
 if(action==="complete-checkpoint"){state.checkpointError="";request(`/api/projects/${state.projectId}/checkpoint/synthesis`).then(({synthesis})=>{state.checkpointSynthesis=synthesis;state.view="checkpoint-review";location.hash="checkpoint-review";render();}).catch(error=>{state.checkpointError=error.message;render();});}
 if(action==="continue-discovery"){state.checkpointSynthesis=null;state.checkpointError="";state.view="chat";location.hash="chat";render();}
 if(action==="new-project"){ $("#projectMenu").classList.add("hidden"); request("/api/projects",{method:"POST",body:JSON.stringify({name:"New project"})}).then(({project})=>{state.chatTurns=[];state.discoveryFacts=[];state.discoveryPlan=null;state.chatLoadedProject=null;state.chatError="";state.chatDraft="";loadMemory(project.id).then(()=>{location.hash="chat";});}).catch(error=>toast(error.message)); }
 if(action==="back-to-intake"){location.hash="intake";}
 if(action==="cancel-intake"){state.intakePreview=false;state.intakeDraft=null;state.view=state.project?"today":"today";location.hash=state.project?"today":"today";render();}
 if(action==="cancel-task-form"){state.showTaskForm=false;render();}
 if(action==="cancel-assumption-form"){state.showAssumptionForm=false;render();}
 if(action==="cancel-link-form"){state.linkingEvidenceId=null;render();}
 if(action==="cancel-experiment-form"){state.showExperimentForm=false;render();}
 if(action==="cancel-experiment-result"){state.completingExperimentId=null;render();}
});
document.addEventListener("keydown", e=>{
 if(e.key!=="Enter" || e.shiftKey || e.isComposing || !e.target.matches("#chatForm textarea")) return;
 e.preventDefault();
 e.target.form.requestSubmit();
});
document.addEventListener("submit", e=>{
 // Static contract retained for browser smoke tests: method:"POST",body:JSON.stringify({message,client_request_id
 if(e.target.id==="chatForm"){e.preventDefault();const message=String(new FormData(e.target).get("message")||"").trim();if(!message){toast("Write a message first.");return;}const optimistic={id:`local-${Date.now()}`,actor_type:"founder",content:message,created_at:new Date().toISOString()};state.chatTurns=[...state.chatTurns,optimistic];state.chatSubmitting=true;state.chatError="";render();request(`/api/projects/${state.projectId}/chat`,{method:"POST",body:JSON.stringify({message,topic:state.chatTopic,session_id:state.chatSessionId,client_request_id:optimistic.id})}).then(result=>{state.chatSubmitting=false;state.chatSessionId=result.founder_turn?.session_id||state.chatSessionId;state.chatTurns=state.chatTurns.map(turn=>turn.id===optimistic.id?(result.founder_turn||turn):turn);if(result.error||result.proposal_error){state.chatDraft=message;const failure=result.error||result.proposal_error;state.chatError=[failure.message,failure.detail].filter(Boolean).join(" ");}else state.chatDraft="";chatRefresh();}).catch(error=>{state.chatSubmitting=false;state.chatDraft=message;state.chatError=error.message;render();});}
 if(e.target.id==="intakeForm"){e.preventDefault();const f=new FormData(e.target);state.onboardingLoading=true;state.onboardingLoadingStartedAt=Date.now();state.onboardingStep=0;clearInterval(onboardingProgressTimer);onboardingProgressTimer=setInterval(()=>{if(state.onboardingLoading&&state.onboardingStep<onboardingSteps().length-1){state.onboardingStep+=1;render();}},900);render();request("/api/onboarding/draft",{method:"POST",body:JSON.stringify(Object.fromEntries(f))}).then(({draft,requires_follow_up})=>{clearInterval(onboardingProgressTimer);state.onboardingLoading=false;state.onboardingLoadingStartedAt=null;if(requires_follow_up){state.intakeDraft=null;state.intakeFollowUpQuestions=draft.follow_up_questions||[];state.view="intake";location.hash="intake";render();return;}state.intakeFollowUpQuestions=[];state.intakeDraft=draft;state.view="onboarding-review";location.hash="onboarding-review";render();}).catch(error=>{clearInterval(onboardingProgressTimer);state.onboardingLoading=false;state.onboardingLoadingStartedAt=null;render();toast(error.message);});}
 if(e.target.id==="onboardingConfirmForm"){e.preventDefault();const f=new FormData(e.target), draft=structuredClone(state.intakeDraft);Object.keys(draft.profile).forEach(key=>draft.profile[key].value=String(f.get(`profile-${key}`)||"").trim());Object.keys(draft.primary_revenue_path).forEach(key=>draft.primary_revenue_path[key].value=String(f.get(`revenue-path-${key}`)||"").trim());draft.industry.primary_industry=String(f.get("industry-primary")||"other");draft.industry.secondary_industry=String(f.get("industry-secondary")||"").trim();draft.industry.industry_rationale=String(f.get("industry-rationale")||"").trim();Object.keys(draft.industry.industry_details).forEach(key=>draft.industry.industry_details[key].value=String(f.get(`industry-detail-${key}`)||"").trim());const accepted={profile:["name",...f.getAll("accept-profile")],revenue_path:f.getAll("accept-revenue-path"),industry:{primary_industry:f.getAll("accept-industry").includes("primary_industry"),secondary_industry:f.getAll("accept-industry").includes("secondary_industry"),industry_rationale:f.getAll("accept-industry").includes("industry_rationale"),industry_confidence:true,details:f.getAll("accept-industry-detail")},assumptions:f.getAll("accept-assumption"),tasks:[]};request("/api/onboarding/confirm",{method:"POST",body:JSON.stringify({draft,accepted})}).then(({project})=>{state.intakeDraft=null;state.planLoading=true;location.hash="chat";loadMemory(project.id);request(`/api/projects/${project.id}/plan`,{method:"POST"}).then(()=>{state.planLoading=false;loadMemory(project.id);}).catch(error=>{state.planLoading=false;render();toast(error.message);});}).catch(error=>toast(error.message));}
 if(e.target.id==="checkpointConfirmForm"){e.preventDefault();const f=new FormData(e.target), profile={};["name","short_description","target_customer","problem_statement","solution_summary","founder_goal","pricing_hypothesis","primary_industry"].forEach(key=>{const value=String(f.get(key)||"").trim();if(value)profile[key]=value;});const firstDollar=String(f.get("first_dollar_path")||"").trim();if(firstDollar)profile.first_dollar_path={offer:firstDollar};request(`/api/projects/${state.projectId}/checkpoint`,{method:"POST",body:JSON.stringify({profile})}).then(()=>{state.checkpointSynthesis=null;state.checkpointError="";return loadMemory().then(()=>loadChatContext(true));}).catch(error=>{state.checkpointError=error.message;render();});}
 if(e.target.id==="evidenceForm"){e.preventDefault();const f=new FormData(e.target);mutate(`/api/projects/${state.projectId}/evidence`,"POST",{source_type:String(f.get("source")).toLowerCase().replaceAll(" ","_"),source_title:f.get("person"),source_person_name:f.get("person"),summary:f.get("summary"),strength:String(f.get("strength")).toLowerCase(),behavior_vs_opinion:String(f.get("signal")).toLowerCase().replaceAll(" ","_")});}
 if(e.target.id==="completionForm"){e.preventDefault();state.completionTaskId=null;mutate(`/api/projects/${state.projectId}/tasks/${e.target.dataset.id}`,"PATCH",{status:"done"});}
 if(e.target.id==="taskForm"){e.preventDefault();const f=new FormData(e.target);state.showTaskForm=false;mutate(`/api/projects/${state.projectId}/tasks`,"POST",{title:f.get("title"),description:f.get("description"),priority:String(f.get("priority")).toLowerCase(),impact_level:f.get("firstRevenue")?"first_revenue":"medium",estimated_minutes:20});}
 if(e.target.id==="assumptionForm"){e.preventDefault();const f=new FormData(e.target);state.showAssumptionForm=false;mutate(`/api/projects/${state.projectId}/assumptions`,"POST",{statement:f.get("statement"),category:f.get("category"),priority:String(f.get("priority")).toLowerCase(),subcategory:f.get("why"),risk_score:65});}
 if(e.target.id==="linkForm"){e.preventDefault();const f=new FormData(e.target);state.linkingEvidenceId=null;mutate(`/api/projects/${state.projectId}/assumption-evidence`,"POST",{evidence_id:e.target.dataset.id,assumption_id:f.get("assumption"),relationship:String(f.get("relationship")).toLowerCase()});}
 if(e.target.id==="experimentForm"){e.preventDefault();const f=new FormData(e.target);state.showExperimentForm=false;mutate(`/api/projects/${state.projectId}/experiments`,"POST",{title:f.get("title"),hypothesis:f.get("hypothesis"),assumption_id:f.get("assumption"),success_metric:f.get("metric"),expected_duration:f.get("due")});}
 if(e.target.id==="experimentResultForm"){e.preventDefault();const f=new FormData(e.target);state.completingExperimentId=null;mutate(`/api/projects/${state.projectId}/experiments/${e.target.dataset.id}`,"PATCH",{status:"completed",test_design:f.get("result"),completed_at:new Date().toISOString()});}
});
document.addEventListener("focusout", e=>{if(e.target.matches("[data-action=edit-memory]")){const map={name:"name",shortDescription:"short_description",targetCustomer:"target_customer",problem:"problem_statement",solution:"solution_summary",pricing:"pricing_hypothesis",revenueModel:"revenue_model",validation:"validation_stage"};const field=map[e.target.dataset.key];if(field) mutate(`/api/projects/${state.projectId}`,"PATCH",{[field]:e.target.textContent.trim()});}if(e.target.matches("[data-action=edit-assumption-why]")){mutate(`/api/projects/${state.projectId}/assumptions/${e.target.dataset.id}`,"PATCH",{subcategory:e.target.textContent.trim()});}});
window.addEventListener("hashchange",render); loadProjects().then(()=>state.projects[0] ? loadMemory(state.projects[0].id) : (state.loading=false,render())).catch(error=>{state.loading=false;render();toast(error.message);});
